 "meaning": "Right-hand"}, {"code": "L", "meaning": "Left-hand"}]}, {"key": "i-chip", "title": "Insert – chipformer", "rows": [{"code": "MF", "meaning": "Multifunction chipformer"}]}, {"key": "p-family", "title": "PICCO tool – family", "rows": [{"code": "PICCO", "meaning": "Solid carbide multifunction tool for Swiss-type machines"}]}, {"key": "p-hand", "title": "PICCO tool – hand", "rows": [{"code": "R", "meaning": "Right-hand"}, {"code": "L", "meaning": "Left-hand"}]}, {"key": "p-type", "title": "PICCO tool – type", "rows": [{"code": "MF", "meaning": "Drilling, facing, internal and external turning"}, {"code": "MFT60", "meaning": "Also threading, 60° profile"}]}, {"key": "p-shank", "title": "PICCO tool – shank", "rows": [{"code": "#", "meaning": "Shank diameter in mm"}]}, {"key": "p-dia", "title": "PICCO tool – diameter", "rows": [{"code": "#", "meaning": "Tool diameter in mm"}]}, {"key": "p-length", "title": "PICCO tool – length", "rows": [{"code": "L##", "meaning": "Usable length in mm"}]}]}$ck$)
